script:
// TASK: build a custom-width (wider than the door template's preview wall) door family, load it
// into a project, and place it hosted in a wall. Runs in a fresh scratch PROJECT document so it
// touches no open model -- against your real project, use the `Document` global instead of `proj`
// and skip the scratch host wall. The scratch project and family documents stay OPEN after the run
// (Close is a gated lifecycle action); close them by title in a later run (documents-create-write-and-close).
var app = UIApplication.Application;
var proj = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + proj.Title + ";");   // repo sweep convention only

// 1. Door template: its file NAME sets the category (Doors). It ships a hidden preview Wall,
//    fixed length ~15 ft, purely for editor context.
string template = null;
foreach (var f in System.IO.Directory.EnumerateFiles(app.FamilyTemplatePath, "Door.rft", System.IO.SearchOption.AllDirectories)) { template = f; break; }
if (template == null) throw new System.Exception("no Door.rft under " + app.FamilyTemplatePath);
var famDoc = Connector.CreateFamilyDocument(template);
System.Console.WriteLine("cleanup-title=" + famDoc.Title + ";");
double doorWidth = 16.0;

// 2. Extend the preview wall PAST the final width BEFORE setting Width. Setting Width beyond the
//    preview wall's length makes the door's opening void cut past the wall end and the commit fails
//    with "Can't make cut-out" (the block rolls back). Extend the wall first.
Connector.WithTransaction(famDoc, () => {
  Autodesk.Revit.DB.Wall preview = null;
  foreach (Autodesk.Revit.DB.Wall w in new Autodesk.Revit.DB.FilteredElementCollector(famDoc).OfClass(typeof(Autodesk.Revit.DB.Wall))) { preview = w; break; }
  var lc = preview.Location as Autodesk.Revit.DB.LocationCurve;
  var line = lc.Curve as Autodesk.Revit.DB.Line;
  var mid = (line.GetEndPoint(0) + line.GetEndPoint(1)) / 2.0;
  var dir = (line.GetEndPoint(1) - line.GetEndPoint(0)).Normalize();
  double half = doorWidth / 2.0 + 6.0;                       // comfortably longer than the door
  lc.Curve = Autodesk.Revit.DB.Line.CreateBound(mid - dir * half, mid + dir * half);
  var fm = famDoc.FamilyManager;
  if (fm.Types.Size == 0) fm.NewType("16x7 Sectional"); else fm.RenameCurrentType("16x7 Sectional");
  foreach (Autodesk.Revit.DB.FamilyParameter p in fm.GetParameters()) { if (p.Definition.Name == "Width") { fm.Set(p, doorWidth); break; } }
  foreach (Autodesk.Revit.DB.FamilyParameter p in fm.GetParameters()) { if (p.Definition.Name == "Height") { fm.Set(p, 7.0); break; } }
  famDoc.Regenerate();
  return true;
});

// 3. Panel as a solid extrusion + a reveal groove as a VOID extrusion (a void auto-cuts any solid
//    it intersects in the SAME family document -- no boolean call). Geometry goes through
//    famDoc.FamilyCreate. Keep the void depth LESS than the panel depth so it grooves, not perforates.
Connector.WithTransaction(famDoc, () => {
  double leftX = -doorWidth/2.0 + 0.05, rightX = doorWidth/2.0 - 0.05, bottomZ = 0.1, topZ = 6.9, yInner = -0.25;
  var plane = Autodesk.Revit.DB.Plane.CreateByNormalAndOrigin(Autodesk.Revit.DB.XYZ.BasisY, new Autodesk.Revit.DB.XYZ(0, yInner, 0));
  var sp = Autodesk.Revit.DB.SketchPlane.Create(famDoc, plane);
  System.Func<double,double,double,double, Autodesk.Revit.DB.CurveArrArray> rect = (x0,z0,x1,z1) => {
    var loop = new Autodesk.Revit.DB.CurveArray();
    loop.Append(Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(x0, yInner, z0), new Autodesk.Revit.DB.XYZ(x1, yInner, z0)));
    loop.Append(Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(x1, yInner, z0), new Autodesk.Revit.DB.XYZ(x1, yInner, z1)));
    loop.Append(Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(x1, yInner, z1), new Autodesk.Revit.DB.XYZ(x0, yInner, z1)));
    loop.Append(Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(x0, yInner, z1), new Autodesk.Revit.DB.XYZ(x0, yInner, z0)));
    var arr = new Autodesk.Revit.DB.CurveArrArray(); arr.Append(loop); return arr;
  };
  famDoc.FamilyCreate.NewExtrusion(true, rect(leftX,bottomZ,rightX,topZ), sp, 0.25);        // solid panel
  double midZ = (bottomZ+topZ)/2.0;
  famDoc.FamilyCreate.NewExtrusion(false, rect(leftX,midZ-0.05,rightX,midZ+0.05), sp, 0.1);  // void groove
  famDoc.Regenerate();
  return true;
});

// 4. Host wall in the project (setup), then LoadFamily BETWEEN blocks: called ON the family doc
//    with the TARGET project passed in; the target must not be modifiable, so it runs at top level.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(proj).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
var hostWallId = Connector.WithTransaction(proj, () => {
  var w = Autodesk.Revit.DB.Wall.Create(proj, Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0,0,0), new Autodesk.Revit.DB.XYZ(30,0,0)), level.Id, false);
  proj.Regenerate();
  return w.Id;
});
var family = famDoc.LoadFamily(proj);
if (family == null) throw new System.Exception("LoadFamily returned null (a family of the same name may already be loaded)");

// 5. Activate the symbol and place the door hosted in the wall.
return Connector.WithTransaction(proj, () => {
  Autodesk.Revit.DB.FamilySymbol symbol = null;
  foreach (var sid in family.GetFamilySymbolIds()) { symbol = proj.GetElement(sid) as Autodesk.Revit.DB.FamilySymbol; break; }
  if (!symbol.IsActive) { symbol.Activate(); }
  proj.Regenerate();
  var wall = proj.GetElement(hostWallId) as Autodesk.Revit.DB.Wall;
  var inst = proj.Create.NewFamilyInstance(new Autodesk.Revit.DB.XYZ(15,0,0), symbol, wall, level, Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  proj.Regenerate();
  var wp = symbol.LookupParameter("Width");
  return new { familyName = family.Name, typeName = symbol.Name, widthFt = wp != null ? wp.AsDouble() : -1, hosted = inst.Host != null };
});
